103	localparam [7:0]
104	    ETH_PRE = 8'h55,
105	    ETH_SFD = 8'hD5;
106	
107	localparam [2:0]
108	    STATE_IDLE = 3'd0,
109	    STATE_PREAMBLE = 3'd1,
110	    STATE_PAYLOAD = 3'd2,
111	    STATE_LAST = 3'd3,
112	    STATE_PAD = 3'd4,
113	    STATE_FCS = 3'd5,
114	    STATE_IFG = 3'd6;
115	
116	reg [2:0] state_reg = STATE_IDLE, state_next;
117	
118	// datapath control signals
119	reg reset_crc;
120	reg update_crc;
121	
122	reg [7:0] s_tdata_reg = 8'd0, s_tdata_next;
123	
124	reg mii_odd_reg = 1'b0, mii_odd_next;
125	reg [3:0] mii_msn_reg = 4'b0, mii_msn_next;
126	
127	reg frame_reg = 1'b0, frame_next;
128	reg frame_error_reg = 1'b0, frame_error_next;
129	reg [7:0] frame_ptr_reg = 0, frame_ptr_next;
130	reg [MIN_LEN_WIDTH-1:0] frame_min_count_reg = 0, frame_min_count_next;
131	
132	reg [7:0] gmii_txd_reg = 8'd0, gmii_txd_next;
133	reg gmii_tx_en_reg = 1'b0, gmii_tx_en_next;
134	reg gmii_tx_er_reg = 1'b0, gmii_tx_er_next;
135	
136	reg s_axis_tready_reg = 1'b0, s_axis_tready_next;
137	
138	reg [PTP_TS_WIDTH-1:0] m_axis_ptp_ts_reg = 0, m_axis_ptp_ts_next;
139	reg [PTP_TAG_WIDTH-1:0] m_axis_ptp_ts_tag_reg = 0, m_axis_ptp_ts_tag_next;
