141	
142	reg start_packet_int_reg = 1'b0, start_packet_int_next;
143	reg start_packet_reg = 1'b0, start_packet_next;
144	reg error_underflow_reg = 1'b0, error_underflow_next;
145	
146	reg [31:0] crc_state = 32'hFFFFFFFF;
147	wire [31:0] crc_next;
148	
149	assign s_axis_tready = s_axis_tready_reg;
150	
151	assign gmii_txd = gmii_txd_reg;
152	assign gmii_tx_en = gmii_tx_en_reg;
153	assign gmii_tx_er = gmii_tx_er_reg;
154	
155	assign m_axis_ptp_ts = PTP_TS_ENABLE ? m_axis_ptp_ts_reg : 0;
156	assign m_axis_ptp_ts_tag = PTP_TAG_ENABLE ? m_axis_ptp_ts_tag_reg : 0;
157	assign m_axis_ptp_ts_valid = PTP_TS_ENABLE || PTP_TAG_ENABLE ? m_axis_ptp_ts_valid_reg : 1'b0;
