211	    gmii_txd_next = {DATA_WIDTH{1'b0}};
212	    gmii_tx_en_next = 1'b0;
213	    gmii_tx_er_next = 1'b0;
214	
215	    start_packet_int_next = start_packet_int_reg;
216	    start_packet_next = 1'b0;
217	    error_underflow_next = 1'b0;
218	
219	    if (s_axis_tvalid && s_axis_tready) begin
220	        frame_next = !s_axis_tlast;
221	    end
222	
223	    if (!clk_enable) begin
224	        // clock disabled - hold state and outputs
225	        gmii_txd_next = gmii_txd_reg;
226	        gmii_tx_en_next = gmii_tx_en_reg;
227	        gmii_tx_er_next = gmii_tx_er_reg;
228	        state_next = state_reg;
229	    end else if (mii_select && mii_odd_reg) begin
230	        // MII odd cycle - hold state, output MSN
231	        mii_odd_next = 1'b0;
232	        gmii_txd_next = {4'd0, mii_msn_reg};
233	        gmii_tx_en_next = gmii_tx_en_reg;
234	        gmii_tx_er_next = gmii_tx_er_reg;
235	        state_next = state_reg;
236	        if (start_packet_int_reg) begin
237	            start_packet_int_next = 1'b0;
238	            start_packet_next = 1'b1;
239	        end
240	    end else begin
241	        case (state_reg)
242	            STATE_IDLE: begin
243	                // idle state - wait for packet
244	                reset_crc = 1'b1;
245	
246	                mii_odd_next = 1'b0;
247	                frame_ptr_next = 1;
248	
249	                frame_error_next = 1'b0;
250	                frame_min_count_next = MIN_FRAME_LENGTH-4-1;
251	
252	                if (s_axis_tvalid && cfg_tx_enable) begin
253	                    mii_odd_next = 1'b1;
254	                    gmii_txd_next = ETH_PRE;
255	                    gmii_tx_en_next = 1'b1;
256	                    state_next = STATE_PREAMBLE;
257	                end else begin
258	                    state_next = STATE_IDLE;
259	                end
260	            end
261	            STATE_PREAMBLE: begin
262	                // send preamble
263	                reset_crc = 1'b1;
264	
265	                mii_odd_next = 1'b1;
266	                frame_ptr_next = frame_ptr_reg + 1;
267	
268	                gmii_txd_next = ETH_PRE;
269	                gmii_tx_en_next = 1'b1;
270	
271	                if (frame_ptr_reg == 6) begin
272	                    s_axis_tready_next = 1'b1;
273	                    s_tdata_next = s_axis_tdata;
274	                    state_next = STATE_PREAMBLE;
275	                end else if (frame_ptr_reg == 7) begin
276	                    // end of preamble; start payload
277	                    frame_ptr_next = 0;
278	                    if (s_axis_tready_reg) begin
279	                        s_axis_tready_next = 1'b1;
280	                        s_tdata_next = s_axis_tdata;
281	                    end
282	                    gmii_txd_next = ETH_SFD;
283	                    if (mii_select) begin
284	                        start_packet_int_next = 1'b1;
285	                    end else begin
286	                        start_packet_next = 1'b1;
287	                    end
288	                    state_next = STATE_PAYLOAD;
289	                end else begin
290	                    state_next = STATE_PREAMBLE;
291	                end
292	            end
293	            STATE_PAYLOAD: begin
294	                // send payload
295	
296	                update_crc = 1'b1;
297	                s_axis_tready_next = 1'b1;
298	
299	                mii_odd_next = 1'b1;
300	
301	                if (frame_min_count_reg) begin
302	                    frame_min_count_next = frame_min_count_reg - 1;
303	                end
304	
305	                gmii_txd_next = s_tdata_reg;
306	                gmii_tx_en_next = 1'b1;
307	
308	                s_tdata_next = s_axis_tdata;
309	
310	                if (!s_axis_tvalid || s_axis_tlast) begin
311	                    s_axis_tready_next = frame_next; // drop frame
312	                    frame_error_next = !s_axis_tvalid || s_axis_tuser[0];
313	                    error_underflow_next = !s_axis_tvalid;
314	
315	                    state_next = STATE_LAST;
316	                end else begin
317	                    state_next = STATE_PAYLOAD;
318	                end
319	            end
320	            STATE_LAST: begin
321	                // last payload word
322	
323	                update_crc = 1'b1;
324	                s_axis_tready_next = 1'b0;
325	
326	                mii_odd_next = 1'b1;
327	
328	                gmii_txd_next = s_tdata_reg;
329	                gmii_tx_en_next = 1'b1;
330	
331	                if (ENABLE_PADDING && frame_min_count_reg) begin
332	                    frame_min_count_next = frame_min_count_reg - 1;
333	                    s_tdata_next = 8'd0;
334	                    state_next = STATE_PAD;
335	                end else begin
336	                    frame_ptr_next = 0;
337	                    state_next = STATE_FCS;
338	                end
339	            end
340	            STATE_PAD: begin
341	                // send padding
342	                s_axis_tready_next = frame_next; // drop frame
343	
344	                update_crc = 1'b1;
345	                mii_odd_next = 1'b1;
346	
347	                gmii_txd_next = 8'd0;
348	                gmii_tx_en_next = 1'b1;
349	
350	                s_tdata_next = 8'd0;
351	
352	                if (frame_min_count_reg) begin
353	                    frame_min_count_next = frame_min_count_reg - 1;
354	                    state_next = STATE_PAD;
355	                end else begin
356	                    frame_ptr_next = 0;
357	                    state_next = STATE_FCS;
358	                end
359	            end
360	            STATE_FCS: begin
361	                // send FCS
362	                s_axis_tready_next = frame_next; // drop frame
363	
364	                mii_odd_next = 1'b1;
365	                frame_ptr_next = frame_ptr_reg + 1;
366	
367	                case (frame_ptr_reg)
368	                    2'd0: gmii_txd_next = ~crc_state[7:0];
369	                    2'd1: gmii_txd_next = ~crc_state[15:8];
370	                    2'd2: gmii_txd_next = ~crc_state[23:16];
371	                    2'd3: gmii_txd_next = ~crc_state[31:24];
372	                endcase
373	                gmii_tx_en_next = 1'b1;
374	                gmii_tx_er_next = frame_error_reg;
375	
376	                if (frame_ptr_reg < 3) begin
377	                    state_next = STATE_FCS;
378	                end else begin
379	                    frame_ptr_next = 0;
380	                    state_next = STATE_IFG;
381	                end
382	            end
383	            STATE_IFG: begin
384	                // send IFG
385	                s_axis_tready_next = frame_next; // drop frame
386	
387	                mii_odd_next = 1'b1;
388	                frame_ptr_next = frame_ptr_reg + 1;
389	
390	                if (frame_ptr_reg < cfg_ifg-1 || frame_reg) begin
391	                    state_next = STATE_IFG;
392	                end else begin
393	                    state_next = STATE_IDLE;
394	                end
395	            end
396	        endcase
397	
398	        if (mii_select) begin
399	            mii_msn_next = gmii_txd_next[7:4];
400	            gmii_txd_next[7:4] = 4'd0;
401	        end
402	    end
403	end
404	
405	always @(posedge clk) begin
406	    state_reg <= state_next;
407	
408	    frame_reg <= frame_next;
409	    frame_error_reg <= frame_error_next;
410	    frame_ptr_reg <= frame_ptr_next;
411	    frame_min_count_reg <= frame_min_count_next;
412	
413	    m_axis_ptp_ts_reg <= m_axis_ptp_ts_next;
414	    m_axis_ptp_ts_tag_reg <= m_axis_ptp_ts_tag_next;
415	    m_axis_ptp_ts_valid_reg <= m_axis_ptp_ts_valid_next;
416	
417	    mii_odd_reg <= mii_odd_next;
418	    mii_msn_reg <= mii_msn_next;
419	
420	    s_tdata_reg <= s_tdata_next;
421	
422	    s_axis_tready_reg <= s_axis_tready_next;
423	
424	    gmii_txd_reg <= gmii_txd_next;
425	    gmii_tx_en_reg <= gmii_tx_en_next;
426	    gmii_tx_er_reg <= gmii_tx_er_next;
427	
428	    if (reset_crc) begin
429	        crc_state <= 32'hFFFFFFFF;
430	    end else if (update_crc) begin
431	        crc_state <= crc_next;
432	    end
433	
434	    start_packet_int_reg <= start_packet_int_next;
435	    start_packet_reg <= start_packet_next;
436	    error_underflow_reg <= error_underflow_next;
437	
438	    if (rst) begin
439	        state_reg <= STATE_IDLE;
440	
441	        frame_reg <= 1'b0;
442	
443	        s_axis_tready_reg <= 1'b0;
444	
445	        m_axis_ptp_ts_valid_reg <= 1'b0;
446	
447	        gmii_tx_en_reg <= 1'b0;
448	        gmii_tx_er_reg <= 1'b0;
449	
450	        start_packet_int_reg <= 1'b0;
451	        start_packet_reg <= 1'b0;
452	        error_underflow_reg <= 1'b0;
453	    end
454	end
455	
456	endmodule
